import numpy as np, collections
def rects_and_regions(gi,go):
    a=np.array(gi); goa=np.array(go)
    # find connected components of 5s (4-connectivity)
    seen=[[False]*a.shape[1] for _ in range(a.shape[0])]
    comps=[]
    for i in range(a.shape[0]):
        for j in range(a.shape[1]):
            if a[i][j]==5 and not seen[i][j]:
                st=[(i,j)]; seen[i][j]=True; cells=[]
                while st:
                    y,x=st.pop(); cells.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        yy,xx=y+dy,x+dx
                        if 0<=yy<a.shape[0] and 0<=xx<a.shape[1] and a[yy][xx]==5 and not seen[yy][xx]:
                            seen[yy][xx]=True; st.append((yy,xx))
                comps.append(cells)
    for k,cells in enumerate(comps):
        ys=[c[0] for c in cells]; xs=[c[1] for c in cells]
        h=max(ys)-min(ys)+1; w=max(xs)-min(xs)+1
        # depth: how many rects contain its bbox? compute containment
        depth=0
        for other in comps:
            oys=[c[0] for c in other]; ox=[c[1] for c in other]
            if min(oys)<=min(ys) and max(oys)>=max(ys) and min(ox)<=min(xs) and max(ox)>=max(xs) and other!=cells:
                depth+=1
        # color mapping: region strictly inside this rect but outside next-smaller rect, or the rect itself
        cols=collections.Counter()
        for i in range(min(ys),max(ys)+1):
            for j in range(min(xs),max(xs)+1):
                if a[i][j]==0:
                    # is this cell inside a smaller rect?
                    inside=False
                    for other in comps:
                        oys=[c[0] for c in other]; ox=[c[1] for c in other]
                        if (min(oys)<i<=max(oys)) and (min(ox)<j<=max(ox)):
                            inside=True;break
                    key=('in' if inside else 'out',depth)
                    cols[key]+=1
                elif a[i][j]==5:
                    cols['rect',depth]+=1
        print('rect',k,'h,w=',h,w,'depth',depth,'cols:',dict(cols))
