# direct: for each square, interior zero cells: k = chebyshev dist to nearest outline cell (of that square)
def predict(gi,go):
    gi=np.array(gi); go=np.array(go)
    sqs=squares(gi)
    H,W=gi.shape
    pred=np.full((H,W),-1,dtype=int)
    for (r0,r1,c0,c1) in sqs:
        if r0==r1 or c0==c1: continue
        outline={(y,x) for y in (r0,r1) for x in range(c0,c1+1)} | {(y,x) for x in (c0,c1) for y in range(r0,r1+1)}
        for y in range(r0,r1+1):
